-- Integration module (integration.db)
-- Directory connections, credentials, sync runs and mappings.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE integrations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        integration_type TEXT NOT NULL,
        description TEXT NOT NULL DEFAULT '',
        endpoint TEXT NOT NULL DEFAULT '',
        username TEXT NOT NULL DEFAULT '',
        search_base TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'inactive'
            CHECK (status IN ('active', 'inactive')),
        sync_enabled INTEGER NOT NULL DEFAULT 0
            CHECK (sync_enabled IN (0, 1)),
        sync_interval INTEGER NOT NULL DEFAULT 60
            CHECK (sync_interval BETWEEN 5 AND 10080),
        next_run_at TEXT,
        last_sync_at TEXT,
        created_by INTEGER,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE integration_ad_users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER NOT NULL,
        object_guid TEXT NOT NULL,
        username TEXT NOT NULL,
        full_name TEXT NOT NULL DEFAULT '',
        email TEXT NOT NULL DEFAULT '',
        phone TEXT NOT NULL DEFAULT '',
        department TEXT NOT NULL DEFAULT '',
        job_title TEXT NOT NULL DEFAULT '',
        distinguished_name TEXT NOT NULL DEFAULT '',
        is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
        last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (integration_id, object_guid),
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE CASCADE
    );

CREATE TABLE integration_connection_tests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER,
        status TEXT NOT NULL CHECK (status IN ('success', 'failed')),
        message TEXT NOT NULL DEFAULT '',
        response_time_ms REAL,
        tested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE SET NULL
    );

CREATE TABLE integration_credentials (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER NOT NULL,
        credential_name TEXT NOT NULL,
        encrypted_value TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (integration_id, credential_name),
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE CASCADE
    );

CREATE TABLE integration_department_mappings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER NOT NULL,
        ad_department TEXT NOT NULL,
        hr_department_id INTEGER,
        hr_department_name TEXT NOT NULL,
        is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (integration_id, ad_department),
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE CASCADE);

CREATE TABLE integration_employee_mappings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER NOT NULL,
        ad_object_guid TEXT NOT NULL,
        hr_employee_id INTEGER,
        mapping_status TEXT NOT NULL DEFAULT 'pending'
            CHECK (mapping_status IN ('pending', 'mapped', 'ignored')),
        reviewed_by INTEGER,
        reviewed_at TEXT,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (integration_id, ad_object_guid),
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE CASCADE);

CREATE TABLE integration_errors (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER,
        error_type TEXT NOT NULL DEFAULT '',
        error_message TEXT NOT NULL DEFAULT '',
        resolved INTEGER NOT NULL DEFAULT 0 CHECK (resolved IN (0, 1)),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE SET NULL
    );

CREATE TABLE integration_sync_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        integration_id INTEGER,
        sync_type TEXT NOT NULL DEFAULT 'manual',
        status TEXT NOT NULL
            CHECK (status IN ('running', 'success', 'failed')),
        message TEXT NOT NULL DEFAULT '',
        started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        completed_at TEXT,
        FOREIGN KEY (integration_id) REFERENCES integrations(id)
            ON DELETE SET NULL
    );

CREATE TABLE directory_connections (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('entra', 'ldap')),
        enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
        server_url TEXT NOT NULL DEFAULT '',
        domain TEXT NOT NULL DEFAULT '',
        base_dn TEXT NOT NULL DEFAULT '',
        user_base_dn TEXT NOT NULL DEFAULT '',
        group_base_dn TEXT NOT NULL DEFAULT '',
        user_filter TEXT NOT NULL DEFAULT '',
        group_filter TEXT NOT NULL DEFAULT '',
        bind_dn TEXT NOT NULL DEFAULT '',
        client_id TEXT NOT NULL DEFAULT '',
        tenant_id TEXT NOT NULL DEFAULT '',
        secret_sealed TEXT NOT NULL DEFAULT '',
        verify_tls INTEGER NOT NULL DEFAULT 1 CHECK (verify_tls IN (0, 1)),
        use_starttls INTEGER NOT NULL DEFAULT 0 CHECK (use_starttls IN (0, 1)),
        ca_bundle_path TEXT NOT NULL DEFAULT '',
        allowed_domains TEXT NOT NULL DEFAULT '',
        provision INTEGER NOT NULL DEFAULT 1 CHECK (provision IN (0, 1)),
        deprovision INTEGER NOT NULL DEFAULT 1 CHECK (deprovision IN (0, 1)),
        allow_signin INTEGER NOT NULL DEFAULT 0 CHECK (allow_signin IN (0, 1)),
        group_nested INTEGER NOT NULL DEFAULT 1 CHECK (group_nested IN (0, 1)),
        default_role TEXT NOT NULL DEFAULT 'member',
        interval_minutes INTEGER NOT NULL DEFAULT 0,
        last_test_at TEXT,
        last_preview_at TEXT,
        last_sync_at TEXT,
        last_status TEXT NOT NULL DEFAULT 'untested',
        last_error TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

CREATE TABLE directory_group_mappings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        connection_id INTEGER NOT NULL,
        group_key TEXT NOT NULL,
        group_name TEXT NOT NULL DEFAULT '',
        role_key TEXT NOT NULL,
        nested INTEGER NOT NULL DEFAULT 1 CHECK (nested IN (0, 1)),
        enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
        note TEXT NOT NULL DEFAULT '',
        member_count INTEGER NOT NULL DEFAULT 0,
        discovered_at TEXT,
        synced_at TEXT,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (connection_id, group_key, role_key),
        FOREIGN KEY (connection_id) REFERENCES directory_connections(id)
            ON DELETE CASCADE
    );

CREATE TABLE directory_sync_runs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        connection_id INTEGER NOT NULL,
        started_at TEXT NOT NULL,
        finished_at TEXT,
        mode TEXT NOT NULL DEFAULT 'preview' CHECK (mode IN ('preview', 'apply')),
        trigger TEXT NOT NULL DEFAULT 'manual'
            CHECK (trigger IN ('manual', 'scheduled', 'test')),
        status TEXT NOT NULL DEFAULT 'running'
            CHECK (status IN ('running', 'success', 'partial', 'failed', 'preview')),
        seen INTEGER NOT NULL DEFAULT 0,
        created INTEGER NOT NULL DEFAULT 0,
        linked INTEGER NOT NULL DEFAULT 0,
        updated INTEGER NOT NULL DEFAULT 0,
        granted INTEGER NOT NULL DEFAULT 0,
        disabled INTEGER NOT NULL DEFAULT 0,
        restored INTEGER NOT NULL DEFAULT 0,
        skipped INTEGER NOT NULL DEFAULT 0,
        errors INTEGER NOT NULL DEFAULT 0,
        actor_id INTEGER,
        error TEXT NOT NULL DEFAULT '',
        summary_json TEXT NOT NULL DEFAULT '{}',
        FOREIGN KEY (connection_id) REFERENCES directory_connections(id)
            ON DELETE CASCADE
    );

CREATE TABLE directory_sync_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        run_id INTEGER NOT NULL,
        object_id TEXT NOT NULL DEFAULT '',
        email TEXT NOT NULL DEFAULT '',
        display_name TEXT NOT NULL DEFAULT '',
        action TEXT NOT NULL,
        detail TEXT NOT NULL DEFAULT '',
        user_id INTEGER,
        plan_json TEXT NOT NULL DEFAULT '{}',
        FOREIGN KEY (run_id) REFERENCES directory_sync_runs(id) ON DELETE CASCADE
    );

CREATE INDEX idx_integration_due
        ON integrations(sync_enabled, next_run_at);
CREATE UNIQUE INDEX idx_integration_name
        ON integrations(name COLLATE NOCASE);
CREATE INDEX idx_integration_status ON integrations(status);
CREATE INDEX idx_ad_user_department
        ON integration_ad_users(department);
CREATE INDEX idx_ad_user_username
        ON integration_ad_users(username);
CREATE INDEX idx_connection_test_integration
        ON integration_connection_tests(integration_id, tested_at);
CREATE INDEX idx_employee_mapping_status
        ON integration_employee_mappings(mapping_status);
CREATE INDEX idx_integration_error_open
        ON integration_errors(resolved, created_at);
CREATE INDEX idx_sync_log_integration
        ON integration_sync_logs(integration_id, started_at);
CREATE INDEX idx_directory_mappings_connection ON directory_group_mappings(connection_id);
CREATE INDEX idx_directory_runs_connection ON directory_sync_runs(connection_id, started_at);
CREATE INDEX idx_directory_items_run ON directory_sync_items(run_id);
